    await expect(page.locator('#cart-count-badge')).toHaveText('7');
    await page.evaluate(() => { window.CartBadge.update(0); const b = document.getElementById('cart-count-badge'); return { text: b.textContent, hidden: b.hasAttribute('hidden'), accessibleNameSource: document.querySelector('a.cart-link') ? document.querySelector('a.cart-link').innerText : null }; });
